import importlib.util
from pathlib import Path
import unittest

spec = importlib.util.spec_from_file_location("data_analysis", Path(__file__).resolve().parents[1] / "scripts/analyze_data_diagnostics.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
CONFIG = "schema=1 role=client pid=1 tick_ms=100 event=CONFIG build=test bits=32\n"
END = "schema=1 role=client pid=1 event=END resource_overflow=0 file_discarded=0 write_failures=0 retired_dropped=0\n"


class DataAnalysis(unittest.TestCase):
    def test_cumulative_not_summed(self):
        result = module.analyze(CONFIG + "schema=1 event=KIND kind=vb upload_bytes=10 shadow_bytes=64\n"
                                "schema=1 event=KIND kind=vb upload_bytes=20 shadow_bytes=64\n" + END)[0]
        self.assertEqual(result["kinds"]["vb"]["upload_bytes"], 20)
        self.assertFalse(result["warnings"])

    def test_transfer_and_handler_are_separate(self):
        result = module.analyze(CONFIG + "schema=1 event=COMMAND queue=device command=1 name=Draw tx=2 data_bytes=30 handler_us=500\n" + END)[0]
        self.assertEqual(result["largest_transfer_commands"][0]["data_bytes"], 30)
        self.assertEqual(result["slowest_handler_commands"][0]["handler_us"], 500)

    def test_resource_lifecycle(self):
        result = module.analyze(CONFIG + "schema=1 event=RESOURCE_LIVE kind=vb id=5 shadow_bytes=64 locks=1\n"
                                "schema=1 event=RESOURCE_RELEASE kind=vb id=5 shadow_bytes=64 locks=2\n" + END)[0]
        self.assertFalse(result["largest_observed_live"])
        self.assertEqual(result["largest_released"][0]["locks"], 2)

    def test_live_samples_are_latest_observations(self):
        result = module.analyze(CONFIG + "schema=1 event=RESOURCE_LIVE kind=vb id=5 shadow_bytes=64 locks=1\n"
                                "schema=1 event=RESOURCE_LIVE kind=vb id=5 shadow_bytes=64 locks=4\n" + END)[0]
        self.assertEqual(len(result["largest_observed_live"]), 1)
        self.assertEqual(result["largest_observed_live"][0]["locks"], 4)

    def test_cap_and_overflow(self):
        result = module.analyze(CONFIG + END.replace("file_discarded=0", "file_discarded=9").replace("resource_overflow=0", "resource_overflow=3"))[0]
        self.assertEqual(len(result["warnings"]), 2)

    def test_missing_end(self):
        self.assertTrue(module.analyze(CONFIG)[0]["warnings"])

    def test_restart_separates_session(self):
        self.assertEqual(len(module.analyze(CONFIG + END + CONFIG.replace("pid=1", "pid=2"))), 2)

    def test_role_mismatch_is_reported(self):
        result = module.analyze(CONFIG + "schema=1 role=host pid=1 event=KIND kind=ib upload_bytes=100\n" + END)[0]
        self.assertNotIn("ib", result["kinds"])
        self.assertTrue(result["warnings"])

    def test_malformed_and_unknown_schema(self):
        with self.assertRaises(ValueError):
            module.analyze("schema=2 event=CONFIG\n")
        self.assertTrue(module.analyze(CONFIG + "not-a-record\n" + END)[0]["warnings"])

    def test_unknown_commands_and_retirement_loss(self):
        result = module.analyze(CONFIG + "schema=1 event=COMMAND queue=device command=514 name=UnknownOverflow data_bytes=5\n"
                                + END.replace("retired_dropped=0", "retired_dropped=4"))[0]
        self.assertEqual(len(result["warnings"]), 2)

    def test_buffer_candidates_are_not_claimed_savings(self):
        result = module.analyze(CONFIG + "schema=1 event=BUFFER kind=vb candidate_writeonly_static_bytes=64 avoided_persistent_shadow_bytes_current=0 range_staging_enabled=0\n"
                                "schema=1 event=BUFFER kind=vb candidate_writeonly_static_bytes=128 avoided_persistent_shadow_bytes_current=0 range_staging_enabled=0\n" + END)[0]
        self.assertEqual(result["buffers"]["vb"]["candidate_writeonly_static_bytes"], 128)
        self.assertEqual(result["buffers"]["vb"]["avoided_persistent_shadow_bytes_current"], 0)

    def test_dynamic_distribution_uses_latest_cumulative_values(self):
        result = module.analyze(CONFIG + "schema=1 event=DYNAMIC_LOCK kind=ib lock_count=1 total_lock_bytes=16 bucket_0_64=1\n"
                                "schema=1 event=DYNAMIC_LOCK kind=ib lock_count=2 total_lock_bytes=48 bucket_0_64=2\n" + END)[0]
        self.assertEqual(result["dynamic_locks"]["ib"]["average_lock_bytes"], 24)
        self.assertFalse(result["warnings"])

    def test_empty_distribution_and_bad_histogram(self):
        result = module.analyze(CONFIG + "schema=1 event=DYNAMIC_LOCK kind=vb lock_count=0 total_lock_bytes=0 bucket_0_64=0\n" + END)[0]
        self.assertIsNone(result["dynamic_locks"]["vb"]["average_lock_bytes"])
        bad = module.analyze(CONFIG + "schema=1 event=DYNAMIC_LOCK kind=vb lock_count=2 bucket_0_64=1\n" + END)[0]
        self.assertIn("histogram count mismatch", bad["warnings"][0])

    def test_recording_state_and_runtime_state_are_separate(self):
        result = module.analyze(CONFIG + "schema=1 event=STATE command=1 name=SetTexture recording=0 total_calls=4 compared_calls=4 same_value_calls=2\n"
                                "schema=1 event=STATE command=1 name=SetTexture recording=1 total_calls=3 compared_calls=2 same_value_calls=1\n" + END)[0]
        self.assertEqual(len(result["states"]), 2)
        self.assertEqual(result["states"]["1:0"]["same_value_ratio"], .5)
        self.assertEqual(result["states"]["1:1"]["compared_same_value_ratio"], .5)

    def test_uncompared_state_does_not_count_as_redundant(self):
        result = module.analyze(CONFIG + "schema=1 event=STATE command=1 name=SetIndices recording=1 total_calls=1 compared_calls=0 same_value_calls=0\n" + END)[0]
        self.assertIsNone(result["states"]["1:1"]["compared_same_value_ratio"])
        self.assertFalse(result["warnings"])

    def test_inconsistent_state_counts(self):
        result = module.analyze(CONFIG + "schema=1 event=STATE command=1 name=SetIndices recording=0 total_calls=1 compared_calls=0 same_value_calls=1\n" + END)[0]
        self.assertIn("inconsistent state equality", result["warnings"][0])


if __name__ == "__main__":
    unittest.main()
